    ///   apiKey: process.env.SMALLEST_API_KEY,
    /// });
    ///
    /// const response = await client.chat.completions.create({
    ///   model: "electron",
    ///   messages: [
    ///     { role: "user", content: "Write one sentence about why the sky is blue." },
    ///   ],
    /// });
    ///
    /// console.log(response.choices[0].message.content);
    /// ```
